package com.nigson.commerce.pricing;
import java.math.*;
import java.sql.Timestamp;
import java.time.Instant;
import java.util.*;
import org.springframework.jdbc.core.JdbcTemplate;
import com.nigson.shared.events.EventCodec;
import com.nigson.shared.problem.*;
import tools.jackson.databind.JsonNode;

/** Explicit single-coupon evaluation. Reservation happens later in the order's T1 transaction. */
public final class JdbcPromotionPriceAdjustments implements PriceAdjustments {
 private final JdbcTemplate jdbc;private final int phase;
 public JdbcPromotionPriceAdjustments(JdbcTemplate jdbc,int phase){this.jdbc=jdbc;this.phase=phase;}
 public Result quote(UUID party,UUID organization,UUID market,String code,Map<UUID,BigDecimal> amounts,Map<UUID,BigDecimal> quantities,BigDecimal delivery,Instant now,Instant expires){
  var discounts=new LinkedHashMap<UUID,BigDecimal>();amounts.keySet().forEach(id->discounts.put(id,BigDecimal.ZERO.setScale(2)));var empty=EventCodec.JSON.createArrayNode();
  if(phase<2){if(code!=null)throw new Problem.Failure(ProblemCode.FEATURE_DISABLED);return new Result(Map.copyOf(discounts),BigDecimal.ZERO.setScale(2),empty,expires);}
  if(code==null)return new Result(Collections.unmodifiableMap(discounts),BigDecimal.ZERO.setScale(2),empty,expires);
  var rows=jdbc.query("SELECT c.id,c.rule_id,c.party_id,c.maximum_uses,c.maximum_uses_per_party,c.reserved_uses,c.consumed_uses,c.expires_at,r.kind,r.revision,r.parameters::text,r.eligibility::text,r.starts_at,r.ends_at,r.market_id FROM commerce.coupon c JOIN commerce.promotion_rule r ON r.id=c.rule_id JOIN commerce.market m ON m.id=r.market_id WHERE lower(c.code)=lower(?) AND c.active AND r.enabled AND m.enabled AND r.market_id=? AND r.starts_at<=? AND r.ends_at>? AND c.expires_at>? FOR SHARE OF c,r",(r,n)->new Object[]{r.getObject(1,UUID.class),r.getObject(2,UUID.class),r.getObject(3,UUID.class),r.getInt(4),r.getInt(5),r.getInt(6),r.getInt(7),r.getTimestamp(8).toInstant(),r.getString(9),r.getLong(10),EventCodec.JSON.readTree(r.getString(11)),EventCodec.JSON.readTree(r.getString(12)),r.getTimestamp(13).toInstant(),r.getTimestamp(14).toInstant(),r.getObject(15,UUID.class)},code,market,Timestamp.from(now),Timestamp.from(now),Timestamp.from(now));
  if(rows.size()!=1)throw PricingValues.rule();var row=rows.getFirst();UUID coupon=(UUID)row[0],rule=(UUID)row[1];if(row[2]!=null&&!party.equals(row[2]))throw PricingValues.rule();int max=(int)row[3],perParty=(int)row[4],reserved=(int)row[5],consumed=(int)row[6];if(reserved+consumed>=max)throw PricingValues.rule();Integer partyCount=jdbc.queryForObject("SELECT count(*) FROM commerce.coupon_redemption WHERE coupon_id=? AND party_id=? AND state IN ('RESERVED','CONSUMED')",Integer.class,coupon,party);if(partyCount==null||partyCount>=perParty)throw PricingValues.rule();String kind=(String)row[8];if(!Set.of("PERCENT","FIXED","FREE_DELIVERY").contains(kind))throw PricingValues.rule();JsonNode params=(JsonNode)row[10],eligibility=(JsonNode)row[11];if(params.path("schemaVersion").asInt(-1)!=1||eligibility.path("schemaVersion").asInt(-1)!=1)throw PricingValues.rule();
  String segment=organization==null?"RETAIL":"DISTRIBUTOR",required=eligibility.path("segment").asString();if(!required.equals("ANY")&&!required.equals(segment))throw PricingValues.rule();BigDecimal subtotal=amounts.values().stream().reduce(BigDecimal.ZERO,BigDecimal::add);if(!eligibility.path("minimumSpend").isNull()&&subtotal.compareTo(new BigDecimal(eligibility.path("minimumSpend").asString()))<0)throw PricingValues.rule();BigDecimal quantity=quantities.values().stream().reduce(BigDecimal.ZERO,BigDecimal::add);if(!eligibility.path("minimumQuantity").isNull()&&quantity.compareTo(new BigDecimal(eligibility.path("minimumQuantity").asString()))<0)throw PricingValues.rule();if(eligibility.path("firstSettledPurchaseOnly").asBoolean()&&Boolean.TRUE.equals(jdbc.queryForObject("SELECT EXISTS(SELECT 1 FROM commerce.sales_order WHERE party_id=? AND payment_status IN ('PAID','PARTIALLY_REFUNDED','REFUNDED'))",Boolean.class,party)))throw PricingValues.rule();
  Set<String> productIds=textIds(eligibility.path("productIds")),categoryIds=textIds(eligibility.path("categoryIds"));Map<UUID,BigDecimal> eligible=new LinkedHashMap<>();for(var entry:amounts.entrySet()){var products=jdbc.queryForList("SELECT p.id FROM commerce.sku s JOIN commerce.product p ON p.id=s.product_id WHERE s.id=?",UUID.class,entry.getKey());if(products.size()!=1)throw PricingValues.rule();UUID product=products.getFirst();boolean productMatch=productIds.isEmpty()||productIds.contains(product.toString());boolean categoryMatch=categoryIds.isEmpty()||!jdbc.queryForList("SELECT category_id FROM commerce.product_category WHERE product_id=?",UUID.class,product).stream().map(UUID::toString).filter(categoryIds::contains).toList().isEmpty();if(productMatch&&categoryMatch)eligible.put(entry.getKey(),entry.getValue());}if(eligible.isEmpty())throw PricingValues.rule();
  BigDecimal totalEligible=eligible.values().stream().reduce(BigDecimal.ZERO,BigDecimal::add),discount=BigDecimal.ZERO,deliveryDiscount=BigDecimal.ZERO;switch(kind){case "PERCENT"->{discount=totalEligible.multiply(new BigDecimal(params.path("percentage").asString())).setScale(2,RoundingMode.HALF_UP);if(!params.path("maximumDiscount").isNull())discount=discount.min(new BigDecimal(params.path("maximumDiscount").asString()));discount=discount.min(totalEligible);}case "FIXED"->discount=new BigDecimal(params.path("amount").asString()).min(totalEligible).setScale(2,RoundingMode.UNNECESSARY);case "FREE_DELIVERY"->{deliveryDiscount=delivery;if(!params.path("maximumDeliveryDiscount").isNull())deliveryDiscount=deliveryDiscount.min(new BigDecimal(params.path("maximumDeliveryDiscount").asString()));}}
  if(discount.signum()>0)discounts.putAll(PricingValues.allocate(eligible,discount,2));var revisions=EventCodec.JSON.createArrayNode();revisions.add(EventCodec.JSON.valueToTree(Map.of("ruleId",rule,"revision",row[9],"couponId",coupon,"couponCode",code,"discount",discount.toPlainString(),"deliveryDiscount",deliveryDiscount.toPlainString())));Instant valid=((Instant)row[7]).isBefore((Instant)row[13])?(Instant)row[7]:(Instant)row[13];return new Result(Collections.unmodifiableMap(discounts),deliveryDiscount,revisions,valid);
 }
 private Set<String> textIds(JsonNode values){if(values==null||!values.isArray())throw PricingValues.rule();var result=new HashSet<String>();for(JsonNode value:values)if(!value.isString()||!result.add(value.asString()))throw PricingValues.rule();return result;}
}
